count: 17,
versionCount: 6,
reference: '氧化铝',
names: ['铝精矿焙烧，回转窑', '铝精矿焙烧，流化床', '氧化铝生产，拜耳法'],
geographies: ['中国，山东省', '中国，河南省', '中国，广西壮族自治区'],
models: ['CUT_OFF', 'CONSEQUENTIAL', 'ATTRIBUTIONAL']
},
{
name: '电力，天然气发电，中压',
uuids: ['2d31db78-e8bb-4417-b3de-50b78a6fb1c9', '5a872cef-b412-491f-a06f-271b3ec3c641'],
count: 9,
versionCount: 4,
reference: '中压电力',
names: ['天然气发电，中压', '联合循环天然气发电，中压'],
geographies: ['中国', '中国，安徽省'],
models: ['CUT_OFF', 'CONSEQUENTIAL']
},
{
name: '运输，货运，公路',
uuids: ['7697bd3c-72c1-49fc-b895-3ed32925a2c3', 'ab2190b1-70a1-40e0-a641-df10a2783256'],
count: 7,
versionCount: 2,
reference: '公路货运',
names: ['公路货运，重型卡车', '公路货运，中型卡车'],
geographies: ['中国', '中国，华东地区'],
models: ['CUT_OFF', 'ATTRIBUTIONAL']
}
];

const cards = [...document.querySelectorAll('.candidate-card')];
const groupChecks = cards.map(card => card.querySelector('.check'));
const groupCount = document.querySelector('.group-count');
const configurationPane = document.querySelector('.configuration-pane');
const activityTitle = document.querySelector('.activity-title');
const targetSelect = document.querySelector('.select-shell');
const tbody = document.querySelector('tbody');
const selectAll = document.querySelector('.table-select-all');
const datasetCount = document.querySelector('.dataset-count');
const clearSelection = document.querySelector('.clear-selection');
const confirmButton = document.querySelector('.confirm-button');
const toast = document.querySelector('.toast');
const tooltip = document.querySelector('.el-tooltip-popper');
const states = groupData.map(group => ({
selected: false,
initialized: false,
selectedRows: new Set(),
targetUuid: [...group.uuids].sort((left, right) => left.localeCompare(right))[0]
}));
let activeIndex = 0;
let toastTimer;

function escapeHtml(value) {
return String(value).replace(/[&<>"']/g, character => ({
'&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
})[character]);
}

function rowsForGroup(group, groupIndex) {
return Array.from({ length: group.count }, (_, index) => ({
key: `${groupIndex}-${index}`,
uuid: group.uuids[index % group.uuids.length],
id: `${String(groupIndex + 1).padStart(2, '0')}${String(index + 1).padStart(2, '0')}d0507-2b6c-4155-b7ce-ca32a8ef9f6c5`,
name: group.names[index % group.names.length],
reference: group.reference,
geography: group.geographies[index % group.geographies.length],
model: group.models[index % group.models.length],
type: index % 3 === 1 ? '消费混合' : '生产混合',
inVersion: index < group.versionCount
}));
}

const rowsByGroup = groupData.map(rowsForGroup);

cards.forEach((card, index) => {
const name = card.querySelector('.candidate-name');
name.textContent = groupData[index].name;
name.dataset.tooltip = groupData[index].name;
});

function hideTooltip() {
tooltip.classList.remove('show');
tooltip.removeAttribute('data-for');
}

function showTooltip(target) {
if (!target?.dataset.tooltip || target.scrollWidth <= target.clientWidth) {
hideTooltip();
return;
}
tooltip.textContent = target.dataset.tooltip;
tooltip.classList.add('show');
tooltip.dataset.for = target.dataset.tooltip;
const targetRect = target.getBoundingClientRect();
const tooltipRect = tooltip.getBoundingClientRect();
const left = Math.min(
window.innerWidth - tooltipRect.width - 8,
Math.max(8, targetRect.left + targetRect.width / 2 - tooltipRect.width / 2)
);
const top = Math.max(8, targetRect.top - tooltipRect.height - 10);
tooltip.style.left = `${left}px`;
tooltip.style.top = `${top}px`;
}

document.addEventListener('mouseover', event => {
const target = event.target.closest('[data-tooltip]');
if (target) showTooltip(target);
});
document.addEventListener('mouseout', event => {
const target = event.target.closest('[data-tooltip]');
if (target && !target.contains(event.relatedTarget)) hideTooltip();
});
window.addEventListener('resize', hideTooltip);
window.addEventListener('scroll', hideTooltip, true);

function showToast(message) {
toast.textContent = message;
toast.classList.add('show');
clearTimeout(toastTimer);
toastTimer = setTimeout(() => toast.classList.remove('show'), 1800);
}

function updateConfirmState() {
confirmButton.disabled = !states.some(state => state.selected && state.selectedRows.size > 0);
}

function updateGroupCount() {
const selected = states.filter(state => state.selected).length;
groupCount.textContent = `已选 ${selected}/${states.length} 组`;
groupChecks.forEach((box, index) => box.classList.toggle('checked', states[index].selected));
updateConfirmState();
}

function updateDatasetSelection() {
const state = states[activeIndex];
const rows = rowsByGroup[activeIndex];
const selected = state.selectedRows.size;
datasetCount.textContent = `已选 ${selected}/${rows.length} 条`;
selectAll.classList.toggle('checked', selected === rows.length && rows.length > 0);
selectAll.classList.toggle('indeterminate', selected > 0 && selected < rows.length);
selectAll.setAttribute('aria-checked', selected > 0 && selected < rows.length ? 'mixed' : String(selected === rows.length && rows.length > 0));
[...tbody.querySelectorAll('tr')].forEach((row, index) => row.querySelector('.check').classList.toggle('checked', state.selectedRows.has(rows[index].key)));
updateConfirmState();
}

function renderActiveGroup() {
const group = groupData[activeIndex];
const state = states[activeIndex];
const rows = rowsByGroup[activeIndex];
activityTitle.textContent = group.name;
activityTitle.dataset.tooltip = group.name;
configurationPane.classList.toggle('is-disabled', !state.selected);
targetSelect.disabled = !state.selected;
targetSelect.innerHTML = group.uuids.map(uuid => `<option value="${escapeHtml(uuid)}">${escapeHtml(uuid)}</option>`).join('');
targetSelect.value = state.targetUuid;
tbody.innerHTML = rows.map(row => `
<tr data-key="${row.key}">
<td class="selection-cell"><span class="check"></span></td>
<td class="uuid-cell" data-tooltip="${escapeHtml(row.uuid)}">${escapeHtml(row.uuid)}</td>
<td data-tooltip="${escapeHtml(row.id)}">${escapeHtml(row.id)}</td>
<td class="dataset-name-cell"><span class="dataset-name-wrap"><span class="link dataset-name-text" data-tooltip="${escapeHtml(row.name)}">${escapeHtml(row.name)}</span>${row.inVersion ? '<span class="tag-version table-version">版本内</span>' : ''}</span></td>
<td data-tooltip="${escapeHtml(row.reference)}">${escapeHtml(row.reference)}</td>
<td data-tooltip="${escapeHtml(row.geography)}">${escapeHtml(row.geography)}</td>
<td data-tooltip="${escapeHtml(row.model)}">${escapeHtml(row.model)}</td>
<td><span class="type-tag${row.type === '消费混合' ? ' consume' : ''}">${row.type}</span></td>
</tr>`).join('');
updateDatasetSelection();
}

cards.forEach((card, index) => {
card.addEventListener('click', () => {
activeIndex = index;
cards.forEach(item => item.classList.remove('active'));
card.classList.add('active');
renderActiveGroup();
});
groupChecks[index].addEventListener('click', event => {
event.stopPropagation();
const state = states[index];
state.selected = !state.selected;
if (state.selected && !state.initialized) {
rowsByGroup[index].forEach(row => state.selectedRows.add(row.key));
state.initialized = true;
}
updateGroupCount();
if (activeIndex === index) renderActiveGroup();
});
});

tbody.addEventListener('click', event => {
const row = event.target.closest('tr');
if (!row) return;
if (event.target.closest('.link')) {
showToast(`将打开数据集详情：${row.querySelector('.link').textContent}`);
return;
}
if (!states[activeIndex].selected || !event.target.closest('.selection-cell')) return;
const key = row.dataset.key;
const selectedRows = states[activeIndex].selectedRows;
selectedRows.has(key) ? selectedRows.delete(key) : selectedRows.add(key);
updateDatasetSelection();
});

selectAll.parentElement.addEventListener('click', () => {
const state = states[activeIndex];
if (!state.selected) return;
const rows = rowsByGroup[activeIndex];
const shouldSelectAll = state.selectedRows.size !== rows.length;
state.selectedRows.clear();
if (shouldSelectAll) rows.forEach(row => state.selectedRows.add(row.key));
updateDatasetSelection();
});

clearSelection.addEventListener('click', () => {
if (!states[activeIndex].selected) return;
states[activeIndex].selectedRows.clear();
updateDatasetSelection();
});

targetSelect.addEventListener('change', () => {
states[activeIndex].targetUuid = targetSelect.value;
});

document.querySelector('.close').addEventListener('click', () => showToast('已取消本次版本生成'));
document.querySelector('.skip-button').addEventListener('click', () => showToast('将跳过合并并继续生成版本'));
confirmButton.addEventListener('click', () => showToast('将合并已选组并继续生成版本'));
document.querySelector('.summary .button').addEventListener('click', () => showToast('将导出全部候选组的同名生产活动明细'));
document.querySelector('.copy-ids').addEventListener('click', async () => {
const ids = rowsByGroup[activeIndex].map(row => row.id).join(',');
try {
await navigator.clipboard.writeText(ids);
} catch {
const input = document.createElement('textarea');
input.value = ids;
input.style.position = 'fixed';
input.style.opacity = '0';
document.body.appendChild(input);
input.select();
document.execCommand('copy');
input.remove();
}
showToast(`已复制 ${rowsByGroup[activeIndex].length} 个身份 ID`);
});

updateGroupCount();
renderActiveGroup();

