:root {
color-scheme: light;
--ink: #182230;
--muted: #667085;
--line: #e4e7ec;
--soft: #f7f8fb;
--brand: #5146ff;
}
* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
margin: 0;
background: #f3f5f8;
color: var(--ink);
font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Microsoft YaHei", sans-serif;
font-size: 15px;
line-height: 1.75;
}
.layout {
display: grid;
grid-template-columns: 280px minmax(0, 1fr);
gap: 28px;
width: min(1760px, calc(100% - 40px));
margin: 24px auto 56px;
align-items: start;
}
.sidebar {
position: sticky;
top: 20px;
max-height: calc(100vh - 40px);
overflow: auto;
padding: 20px 16px;
background: rgba(255, 255, 255, .98);
border: 1px solid #dfe3eb;
border-radius: 12px;
box-shadow: 0 12px 30px rgba(16, 24, 40, .06);
}
.toc-label {
margin: 0;
padding: 0 8px 4px;
color: #344054;
font-size: 18px;
font-weight: 700;
}
.toc-version { margin: 0 0 12px; padding: 0 8px 14px; border-bottom: 1px solid var(--line); color: var(--muted); font-size: 13px; }
.sidebar #TOC ul { margin: 0; padding: 0; list-style: none; }
.sidebar #TOC ul ul { padding-left: 14px; }
.sidebar #TOC li { margin: 2px 0; }
.sidebar #TOC a {
display: block;
padding: 7px 8px;
border-radius: 6px;
color: #344054;
font-size: 14px;
line-height: 1.4;
text-decoration: none;
}
.sidebar #TOC ul ul a { color: var(--muted); font-size: 13px; }
.sidebar #TOC a:hover, .sidebar #TOC a.active { color: var(--brand); background: #f1f0ff; }
.paper {
min-width: 0;
background: #fff;
border: 1px solid #dfe3eb;
border-radius: 12px;
box-shadow: 0 12px 36px rgba(16, 24, 40, .07);
overflow: hidden;
}
.paper > section.level1 { max-width: 1440px; margin: 0 auto; padding: 42px 48px 64px; }
.paper > section.level1 > h1 {
margin: 0 0 22px;
padding-bottom: 24px;
border-bottom: 1px solid var(--line);
font-size: 34px;
line-height: 1.35;
letter-spacing: -.02em;
}
.paper > section.level1 > h1::before {
display: block;
margin-bottom: 10px;
content: "PRODUCT REQUIREMENT DOCUMENT";
color: var(--brand);
font-size: 12px;
font-weight: 800;
letter-spacing: .08em;
}
h2 { margin: 44px 0 16px; padding-bottom: 8px; border-bottom: 1px solid var(--line); font-size: 23px; }
h3 { margin: 32px 0 12px; font-size: 19px; }
h4 { margin: 26px 0 10px; font-size: 16px; }
p { margin: 8px 0 14px; }
a { color: #315efb; }
blockquote { margin: 0 0 22px; padding: 9px 14px; border-left: 3px solid var(--brand); background: #f5f4ff; color: #475467; }
blockquote p { margin: 0; }
code { padding: 2px 5px; border-radius: 4px; background: #f2f4f7; color: #344054; font-family: "SFMono-Regular", Consolas, monospace; font-size: .9em; }
table { width: 100%; margin: 14px 0 24px; border-collapse: collapse; font-size: 14px; }
th, td { padding: 10px 12px; border: 1px solid var(--line); text-align: left; vertical-align: top; overflow-wrap: anywhere; }
th { background: var(--soft); color: #344054; font-weight: 600; }
tr:nth-child(even) td { background: #fcfcfd; }
ul, ol { padding-left: 24px; }
li { margin: 4px 0; }
.prototype-embed { margin: 18px 0 28px; }
.prototype-stage { width: 100%; overflow: hidden; border: 1px solid #dfe3eb; border-radius: 12px; background: #f5f6f8; }
.prototype-stage iframe { display: block; border: 0; transform-origin: top left; background: #f5f6f8; }
.prototype-embed figcaption { margin-top: 8px; color: var(--muted); font-size: 13px; text-align: center; }
@media (max-width: 980px) {
.layout { display: block; width: min(100% - 24px, 900px); margin-top: 12px; }
.sidebar { position: static; max-height: none; margin-bottom: 14px; }
.sidebar #TOC > ul { columns: 2; column-gap: 18px; }
.paper > section.level1 { padding: 30px 28px 50px; }
}
@media (max-width: 640px) {
.sidebar #TOC > ul { columns: 1; }
.paper > section.level1 { padding: 24px 18px 40px; }
}
@media print {
body { background: #fff; font-size: 11pt; }
.layout { display: block; width: auto; margin: 0; }
.sidebar { display: none; }
.paper { border: 0; box-shadow: none; }
.paper > section.level1 { max-width: none; padding: 0; }
.prototype-embed { break-inside: avoid; }
}

